namespace life {double genomeDistanceBounded(const GenomeDescriptor&,const GenomeDescriptor&,double);struct NativeSimulationTestAccess {
  static bool brain(const Nnue& a,const Nnue& b){return std::tie(a.inputWeights,a.hiddenBias,a.accumulator,a.outputWeights,a.outputBias,a.output,a.active)==std::tie(b.inputWeights,b.hiddenBias,b.accumulator,b.outputWeights,b.outputBias,b.output,b.active);}
  static bool rng(const NativeSimulation& a,const NativeSimulation& b){return a.random_.checkpoint()==b.random_.checkpoint()&&a.nextId_==b.nextId_&&a.births_==b.births_&&a.deathsByCause_==b.deathsByCause_&&a.nextBrainGenomeId_==b.nextBrainGenomeId_;}
  static void smallHistory(NativeSimulation& s){s.lineageLimit_=5;}
  static void pruneFixture(NativeSimulation& s){const auto base=s.organisms_.front();for(int index=1;index<200;++index){auto dead=base;dead.id=index+1;dead.parentId=index/2+1;dead.living=false;dead.lineage->deathTick=10;dead.deathCauseCode=DeathCause::OldAge;dead.lineage->deathCause="Old age";s.slotById_[dead.id]=s.organisms_.size();s.organisms_.push_back(std::move(dead));}s.nextId_=201;s.deadCount_=199;s.lineageLimit_=30;s.selectedId_=30;s.watchedId_=90;}
  static void prune(NativeSimulation& s){s.pruneLineage();s.rebuildRegionIndex();}
  static void referencePrune(NativeSimulation& s){
    std::unordered_map<int,size_t> slots;std::unordered_map<int,int> children;for(size_t index=0;index<s.organisms_.size();++index){slots[s.organisms_[index].id]=index;if(s.organisms_[index].parentId>=0)++children[s.organisms_[index].parentId];}
    std::unordered_set<int> protectedIds,removed;const auto protect=[&](int id){while(id>=0&&protectedIds.insert(id).second){const auto found=slots.find(id);if(found==slots.end())break;id=s.organisms_[found->second].parentId;}};for(const auto& o:s.organisms_)if(o.living)protect(o.id);protect(s.selectedId_);protect(s.watchedId_);
    bool progress=true;while(s.deadCount_>s.lineageLimit_&&progress){progress=false;for(const auto& o:s.organisms_){if(s.deadCount_<=s.lineageLimit_)break;if(o.living||protectedIds.contains(o.id)||removed.contains(o.id)||children[o.id]>0)continue;removed.insert(o.id);--s.deadCount_;if(o.parentId>=0)--children[o.parentId];progress=true;}}
    std::vector<int> activeIds;for(const auto slot:s.activeSlots_)activeIds.push_back(slot<s.organisms_.size()&&s.organisms_[slot].living?s.organisms_[slot].id:-1);s.organisms_.erase(std::remove_if(s.organisms_.begin(),s.organisms_.end(),[&](const Organism& o){return removed.contains(o.id);}),s.organisms_.end());s.slotById_.clear();for(size_t index=0;index<s.organisms_.size();++index)s.slotById_[s.organisms_[index].id]=index;s.activeSlots_.clear();for(const int id:activeIds){const auto found=s.slotById_.find(id);if(id<0||found==s.slotById_.end()){s.activeSlots_.push_back(SIZE_MAX);continue;}s.organisms_[found->second].activeIndex=s.activeSlots_.size();s.activeSlots_.push_back(found->second);}s.familyRoot_=-2;s.familyRecords_=SIZE_MAX;s.rebuildRegionIndex();s.rebuildOwnerSlots();
  }
};}
void require(bool value,const char* message){if(!value)throw std::runtime_error(message);}
#define ORGANISM_FIELDS(o) std::tie(o.id,o.parentId,o.lineage->generation,o.lineage->birthTick,o.lineage->deathTick,o.x,o.y,o.energy,o.minerals,o.lifetime,o.damage,o.mutability,o.neuralMutability,o.birthDistance,o.moveRange,o.moveCount,o.direction,o.rotation,o.living,o.isProducer,o.isMover,o.isConsumer,o.isAttacker,o.thermalStress,o.hypoxiaStress,o.oxygenTolerance,o.stressRecovery,o.frailty,o.respiratoryRisk,o.deathCauseCode,o.lineage->deathCause,o.perceptionRadius,o.senseChannels,o.neuralCost,o.carrionConsumed,o.nutrientsReleased,o.decompositionEnergy,o.lineage->totalDescendants,o.lineage->mutations,o.lastFeatures,o.lastOutputs,o.lastAction,o.activeIndex,o.brainGenomeId,o.speciesId,o.lineage->directOffspring,o.lineage->offspringCountComplete)
void compareState(const life::NativeSimulation& a,const life::NativeSimulation& b){
  require(life::NativeSimulationTestAccess::rng(a,b),"Random stream or lifecycle counters diverged");
  require(a.cells==b.cells&&a.owners==b.owners&&a.world.terrain==b.world.terrain&&a.world.resources==b.world.resources&&a.world.resourceAmount==b.world.resourceAmount&&a.world.nutrients==b.world.nutrients&&a.world.elevation==b.world.elevation&&a.world.habitat==b.world.habitat&&a.moisture==b.moisture,"World layers diverged");
  const auto& left=a.organisms();const auto& right=b.organisms();require(left.size()==right.size(),"Lineage count diverged");
  for(size_t index=0;index<left.size();++index){const auto& x=left[index];const auto& y=right[index];if(ORGANISM_FIELDS(x)!=ORGANISM_FIELDS(y))throw std::runtime_error("Organism state diverged: "+std::to_string(x.id));require(x.cells.size()==y.cells.size(),"Body size diverged");for(size_t cell=0;cell<x.cells.size();++cell){const auto& c=x.cells[cell];const auto& d=y.cells[cell];require(std::tie(c.type,c.x,c.y,c.durability)==std::tie(d.type,d.x,d.y,d.durability),"Body state diverged");}require(bool(x.brain)==bool(y.brain),"Brain presence diverged");if(x.brain)require(life::NativeSimulationTestAccess::brain(*x.brain,*y.brain),"Neural weights, accumulator or outputs diverged");}
  const auto x=a.atlasSnapshot(),y=b.atlasSnapshot();require(x.species.size()==y.species.size()&&x.events.size()==y.events.size()&&x.timeline.size()==y.timeline.size(),"Atlas sizes diverged");
  for(size_t index=0;index<x.species.size();++index){const auto& c=x.species[index];const auto& d=y.species[index];require(std::tie(c.id,c.parentId,c.representativeId,c.population,c.peakPopulation,c.firstTick,c.lastTick,c.missingScans,c.descendantSpecies,c.extinct,c.extinctionCause,c.representative,c.habitatPopulation,c.averageElevation)==std::tie(d.id,d.parentId,d.representativeId,d.population,d.peakPopulation,d.firstTick,d.lastTick,d.missingScans,d.descendantSpecies,d.extinct,d.extinctionCause,d.representative,d.habitatPopulation,d.averageElevation),"Species identity diverged");}
  std::cout<<"Equivalent simulation, RNG, organisms, neural runtime and species: "<<a.tickCount()<<" ticks\n";
}
void compare(const char* first,const char* second){life::NativeSimulation a(1024,640,.2,500,1,1),b(1024,640,.2,500,1,1);a.load(first);b.load(second);compareState(a,b);}
